#include "globe.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <set>
using namespace uaa;
void check(bool v,const char* what){if(!v)throw std::runtime_error(what);}
int main(int argc,char** argv){try{check(argc==2,"Expected data directory");auto countries=readJson(fs::path(argv[1])/"globe/countries.json");
 for(double rotation:{-179.,0.,85.,179.})for(double tilt:{-80.,0.,65.})for(double zoom:{.65,1.,GlobeView::maxZoom}){GlobeView view{rotation,tilt,zoom};for(int lat=-80;lat<=80;lat+=20)for(int lon=-180;lon<=180;lon+=20){double x,y,a,b;if(!view.project(lon,lat,x,y))continue;check(view.unproject(x,y,a,b),"Visible point must invert");check(std::abs(std::remainder(a-lon,360.))<.0001&&std::abs(b-lat)<.0001,"Projection roundtrip across rotation/tilt/zoom");}}
 check(std::abs(GlobeView{0,0,GlobeView::maxZoom}.scaleMeters()-1000000.)<1e-6,"Maximum zoom scale is exactly 1000 km");
 auto capitals=readJson(fs::path(argv[1])/"globe/capitals.json");check(capitals["countries"].size()==countries["features"].size(),"Every map territory must have a capital record");std::set<std::string> mapped;for(const auto& r:capitals["countries"]){check(mapped.insert(r["country"]).second,"Duplicate country capital record");if(r["cities"].empty())check(!r["note_cs"].get<std::string>().empty(),"No-capital territory requires explanation");std::set<std::string> seen;for(const auto& c:r["cities"]){check(seen.insert(c["name"]).second,"Duplicate capital");check(c["lat"].get<double>()>=-90&&c["lat"].get<double>()<=90&&std::abs(c["lon"].get<double>())<=180,"Capital coordinates valid");}}
 for(const auto& f:countries["features"])check(mapped.count(f["properties"]["name"]),"Missing country capital mapping");
 auto has=[&](const std::string& code,const std::string& city){for(const auto& r:capitals["countries"])if(r["code"]==code)for(const auto& c:r["cities"])if(c["name"]==city)return true;return false;};check(has("GNQ","Ciudad de la Paz")&&!has("GNQ","Malabo"),"Equatorial Guinea updated in 2026");check(has("PLW","Ngerulmud")&&!has("PLW","Melekeok"),"Palau capital is Ngerulmud");check(has("BDI","Gitega")&&has("KAZ","Astana"),"Current capital names");check(has("LKA","Sri Jayawardenepura Kotte")&&has("BOL","Sucre")&&has("NLD","Amsterdam"),"Constitutional capitals retained");check(has("ZAF","Bloemfontein")&&has("ZAF","Cape Town")&&has("ZAF","Pretoria"),"All three South African capitals");check(!has("JPN","Kyoto")&&!has("NGA","Lagos")&&!has("PHL","Baguio"),"Historical capitals excluded");
 double lon,lat;check(!GlobeView{}.unproject(0,0,lon,lat),"Outside globe is not a location");
 check(globeCountryAt(countries,14.4378,50.0755)=="Czechia","Prague is Czech land");check(globeCountryAt(countries,-30,0).empty(),"Atlantic is ocean");check(!globeCountryAt(countries,151.2,-33.86).empty(),"Sydney is land");check(!globeCountryAt(countries,-77.04,-12.05).empty(),"Lima is land");check(!globeCountryAt(countries,178,-17.8).empty(),"Fiji dateline side is land");check(globeCountryAt(countries,0,-89)=="Antarctica","Polar land");
 GlobeGesture gesture;GlobeView view;auto before=view;gesture.down(500,400);gesture.motion(503,402,view);check(gesture.up(),"Jitter remains click");check(view.rotation==before.rotation,"Jitter does not rotate");gesture.down(500,400);gesture.motion(580,440,view);check(!gesture.up(),"Drag never becomes base click");check(view.rotation!=before.rotation&&view.tilt!=before.tilt,"Drag rotates both axes during placement");gesture.down(500,400);gesture.motion(500,20000,view);check(std::abs(view.tilt)<=89,"Pole clamp");gesture.cancel();check(!gesture.up(),"Focus loss cancels click");
 std::cout<<"PASS: capitals for 242 territories, current names/roles, globe projection/inverse at three zooms, ocean/land/poles/dateline, drag threshold, both axes and cancelled clicks\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
